//! The sole generated IPC contract. Framing validates length before allocating.
use prost::Message;
use std::io::{self, Read, Write};

#[allow(
    clippy::all,
    clippy::pedantic,
    reason = "Generated by Prost; lint the handwritten framing and build script instead"
)]
pub mod wire {
    include!(concat!(env!("OUT_DIR"), "/mik.v1.rs"));
}

#[allow(clippy::all, clippy::pedantic, reason = "Generated by Prost")]
pub mod music {
    include!(concat!(env!("OUT_DIR"), "/mik.music.v2.rs"));
}

pub const MUSIC_PREFACE: [u8; 6] = *b"MIKM\0\x02";
pub const MUSIC_FRAME_BYTES: usize = 128 * 1024;
// Assign a new bit to a new representation version; never change an existing bit's meaning.
pub const MUSIC_ENCODED_AUDIO_V1: u8 = 0b01;
pub const MUSIC_NOTE_EVENTS_V1: u8 = 0b10;
pub const MUSIC_OUTPUTS: u8 = MUSIC_ENCODED_AUDIO_V1 | MUSIC_NOTE_EVENTS_V1;

pub const VERSION: u32 = 1;
pub const MAX_FRAME_BYTES: usize = 256 * 1024;
pub const CAPABILITIES: &[&str] = &["status.v1", "paper-state.v1"];
pub const MAX_PLAYERS: usize = 256;

/// Validate before allocation, including the unsigned high bit of the prefix.
/// # Errors
/// Rejects zero and oversized frames.
pub fn frame_length(prefix: [u8; 4]) -> io::Result<usize> {
    let length = u32::from_be_bytes(prefix) as usize;
    if length == 0 || length > MAX_FRAME_BYTES {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            "invalid frame length",
        ));
    }
    Ok(length)
}

/// # Errors
/// Rejects truncated frames and invalid Protobuf payloads.
pub fn read_frame(reader: &mut impl Read) -> io::Result<wire::Envelope> {
    let mut prefix = [0; 4];
    reader.read_exact(&mut prefix)?;
    let mut bytes = vec![0; frame_length(prefix)?];
    reader.read_exact(&mut bytes)?;
    wire::Envelope::decode(bytes.as_slice())
        .map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))
}

/// # Errors
/// Rejects oversized messages before allocating or writing any bytes.
pub fn write_frame(writer: &mut impl Write, message: &wire::Envelope) -> io::Result<()> {
    let length = message.encoded_len();
    let prefix = u32::try_from(length)
        .map_err(io::Error::other)?
        .to_be_bytes();
    frame_length(prefix)?;
    writer.write_all(&prefix)?;
    writer.write_all(&message.encode_to_vec())
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::io::Cursor;

    #[test]
    fn length_limits_are_checked_before_allocation() {
        for n in [0, u32::try_from(MAX_FRAME_BYTES).unwrap() + 1, u32::MAX] {
            assert!(frame_length(n.to_be_bytes()).is_err());
        }
        assert_eq!(
            frame_length(u32::try_from(MAX_FRAME_BYTES).unwrap().to_be_bytes()).unwrap(),
            MAX_FRAME_BYTES
        );
    }

    #[test]
    fn concatenated_frames_and_truncation() {
        let message = wire::Envelope {
            request_id: 7,
            ..Default::default()
        };
        let mut bytes = vec![];
        write_frame(&mut bytes, &message).unwrap();
        let one = bytes.clone();
        bytes.extend_from_slice(&one);
        let mut cursor = Cursor::new(bytes);
        assert_eq!(read_frame(&mut cursor).unwrap(), message);
        assert_eq!(read_frame(&mut cursor).unwrap(), message);
        for n in 0..one.len() {
            assert!(read_frame(&mut Cursor::new(&one[..n])).is_err());
        }
    }

    #[test]
    fn frozen_java_fixture_has_identical_protobuf_encoding() {
        let bytes = include_bytes!("../../../tests/interop/hello-v1.bin");
        let envelope = wire::Envelope::decode(bytes.as_slice()).unwrap();
        let Some(wire::envelope::Body::Hello(hello)) = &envelope.body else {
            panic!("hello required");
        };
        assert_eq!(hello.game_instance, "fixture-paper");
        assert_eq!(hello.protocol_version, 1);
        assert_eq!(hello.role, i32::from(wire::ConnectionRole::PaperState));
        assert_eq!(hello.capabilities, CAPABILITIES);
        assert_eq!(envelope.encode_to_vec(), bytes);
    }

    #[test]
    fn assistant_v6_rich_text_has_the_same_wire_content_as_java() {
        use wire::{
            assistant_block::Content, assistant_part::Target, assistant_span::Style,
            assistant_table::Alignment,
        };

        let bytes = fixture_bytes(include_str!(
            "../../../tests/interop/assistant-blocks-v6.hex"
        ));
        let envelope = wire::Envelope::decode(bytes.as_slice()).unwrap();
        let Some(wire::envelope::Body::Response(response)) = &envelope.body else {
            panic!("response required");
        };
        let Some(wire::response::Result::Assistant(result)) = &response.result else {
            panic!("assistant result required");
        };
        let Some(wire::assistant_result::Outcome::Reply(reply)) = &result.outcome else {
            panic!("assistant reply required");
        };
        let [heading, block, table, code] = reply.blocks.as_slice() else {
            panic!("heading, list, table, and code required")
        };
        assert!(matches!(&heading.content, Some(Content::Heading(heading)) if heading.level == 2));
        let Some(Content::List(list)) = &block.content else {
            panic!("list required");
        };
        let [first, nested] = list.children[0].blocks.as_slice() else {
            panic!("nested list required")
        };
        let Some(Content::Paragraph(first)) = &first.content else {
            panic!("paragraph required")
        };
        let [building, distance, guide] = first.parts.as_slice() else {
            panic!("first item has three ordered parts")
        };
        assert_eq!(list.first_number, Some(3));
        assert_eq!(building.spans[0].text, "The ");
        assert_eq!(building.spans[1].text, "Glasshouse");
        assert_eq!(
            building.spans[1].styles,
            [Style::Bold as i32, Style::Italic as i32]
        );
        assert!(
            matches!(&building.target, Some(Target::Url(url)) if url == "https://mcmik.top/buildings/0123456789abcdef0123456789abcdef")
        );
        assert_eq!(distance.spans[0].text, " · 28 blocks away · ");
        assert!(distance.target.is_none());
        assert!(
            matches!(&guide.target, Some(Target::Url(url)) if url == "https://mcmik.top/en/wiki?section=visitor-guide")
        );
        let Some(Content::List(nested)) = &nested.content else {
            panic!("nested list required")
        };
        assert_eq!(nested.children[0].checked, Some(false));
        let Some(Content::Paragraph(second)) = &nested.children[0].blocks[0].content else {
            panic!("paragraph required")
        };
        let [question, command] = second.parts.as_slice() else {
            panic!("second item has a follow-up and plain text")
        };
        assert_eq!(question.spans[0].text, "Where is the entrance?");
        assert!(matches!(&question.target, Some(Target::AskLabel(_))));
        assert_eq!(command.spans[1].text, "/plot");
        assert_eq!(command.spans[1].styles, [Style::Code as i32]);
        assert!(command.target.is_none());
        let Some(Content::Table(table)) = &table.content else {
            panic!("table required")
        };
        assert_eq!(
            table.columns,
            [Alignment::Left as i32, Alignment::Right as i32]
        );
        assert_eq!(
            table.rows[0].cells[0].parts[0].spans[0].styles,
            [Style::Strikethrough as i32]
        );
        assert!(matches!(&code.content, Some(Content::Code(code))
            if code.language == "sh" && code.text == "echo first\necho second"));
        assert_eq!(
            wire::Envelope::decode(envelope.encode_to_vec().as_slice()).unwrap(),
            envelope
        );
    }

    #[test]
    fn assistant_tool_call_matches_the_shared_fixture() {
        use wire::{game_query_job::Operation, response::Result};

        let bytes = fixture_bytes(include_str!(
            "../../../tests/interop/assistant-tool-call-v9.hex"
        ));
        let envelope = wire::Envelope::decode(bytes.as_slice()).unwrap();
        let Some(wire::envelope::Body::Response(response)) = &envelope.body else {
            panic!("response required");
        };
        let Some(Result::GameQuery(work)) = &response.result else {
            panic!("game query required");
        };
        let Some(Operation::AssistantTool(query)) =
            work.job.as_ref().and_then(|job| job.operation.as_ref())
        else {
            panic!("assistant game query required");
        };
        assert_eq!(query.player_uuid, "00000000-0000-4000-8000-000000000001");
        assert_eq!(query.turn_id, "00000000-0000-4000-8000-000000000002");
        assert_eq!(query.name, "game_read_weather");
        assert_eq!(query.arguments_json, r#"{"units":"seconds"}"#);
        assert_eq!(envelope.encode_to_vec(), bytes);
    }

    #[test]
    fn assistant_ask_carries_papers_descriptors_in_the_shared_fixture() {
        use wire::{assistant_command, envelope::Body, request};

        let bytes = fixture_bytes(include_str!(
            "../../../tests/interop/assistant-tools-ask-v9.hex"
        ));
        let envelope = wire::Envelope::decode(bytes.as_slice()).unwrap();
        let Some(Body::Request(request)) = &envelope.body else {
            panic!("request required");
        };
        let Some(request::Operation::Assistant(command)) = &request.operation else {
            panic!("assistant command required");
        };
        let Some(assistant_command::Operation::Ask(ask)) = &command.operation else {
            panic!("assistant ask required");
        };
        let [tool] = ask.game_tools.as_slice() else {
            panic!("expected a single descriptor");
        };
        assert_eq!(tool.name, "game_read_weather");
        assert_eq!(tool.description, "Read the requester's weather");
        assert_eq!(
            tool.input_schema_json,
            r#"{"type":"object","properties":{"units":{"type":"string"}}}"#
        );
        assert_eq!(envelope.encode_to_vec(), bytes);
    }

    fn fixture_bytes(fixture: &str) -> Vec<u8> {
        let fixture = fixture.trim();
        (0..fixture.len())
            .step_by(2)
            .map(|offset| u8::from_str_radix(&fixture[offset..offset + 2], 16).unwrap())
            .collect()
    }
}
